import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id) max-heap by price, then earliest seq
    sell_heap = []  # (price, seq, id) min-heap by price, then earliest seq
    book = {}  # id -> dict with side, price, qty, seq, active
    seq_counter = 0

    def add_resting(id_, side, price, qty, seq):
        book[id_] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, id_))
        else:
            heapq.heappush(sell_heap, (price, seq, id_))

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            id_ = order[1]
            if id_ in book and book[id_]['active']:
                book[id_]['active'] = False
            continue

        id_ = order[1]
        side = order[2]
        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        seq = seq_counter
        seq_counter += 1

        remaining = qty
        if side == 'buy':
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]
                info = book.get(top_id)
                if info is None or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and top_price > price:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([id_, top_id, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['active'] = False
                    heapq.heappop(sell_heap)
            if typ == 'limit' and remaining > 0:
                add_resting(id_, side, price, remaining, seq)
        else:  # sell
            while remaining > 0 and buy_heap:
                top_neg_price, top_seq, top_id = buy_heap[0]
                top_price = -top_neg_price
                info = book.get(top_id)
                if info is None or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and top_price < price:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([top_id, id_, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['active'] = False
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                add_resting(id_, side, price, remaining, seq)

    return trades

